public interface PaymentMethod {
    // Contract methods for all payment rails
    boolean validateCredentials();
    double calculateFee(double amount);
    boolean processPayment(double amount);
    String getPaymentType();
    String getMaskedIdentifier();
}

// 1. Credit Card Implementation
class CreditCardPayment implements PaymentMethod {
    private String cardNumber;
    private String cvv;
    private String expiryDate;

    public CreditCardPayment(String cardNumber, String cvv, String expiryDate) {
        this.cardNumber = (cardNumber != null) ? cardNumber.replaceAll("\\s+", "") : "";
        this.cvv = cvv;
        this.expiryDate = expiryDate;
    }

    @Override
    public boolean validateCredentials() {
        return cardNumber.length() == 16 && cvv != null && cvv.length() == 3;
    }

    @Override
    public double calculateFee(double amount) {
        return amount * 0.025; // 2.5% fee
    }

    @Override
    public boolean processPayment(double amount) {
        if (!validateCredentials()) return false;
        System.out.printf("Routing $%.2f through Card Payment Network... Approved.%n", amount);
        return true;
    }

    @Override
    public String getPaymentType() { return "CREDIT_CARD"; }

    @Override
    public String getMaskedIdentifier() {
        if (cardNumber.length() >= 4) {
            return "************" + cardNumber.substring(cardNumber.length() - 4);
        }
        return "CARD-UNKNOWN";
    }
}

// 2. UPI Implementation
class UpiPayment implements PaymentMethod {
    private String upiId;

    public UpiPayment(String upiId) {
        this.upiId = upiId;
    }

    @Override
    public boolean validateCredentials() {
        return upiId != null && upiId.contains("@") && upiId.length() >= 5;
    }

    @Override
    public double calculateFee(double amount) {
        return 0.50; // $0.50 flat fee
    }

    @Override
    public boolean processPayment(double amount) {
        if (!validateCredentials()) return false;
        System.out.printf("Routing $%.2f via UPI Instant Transfer (%s)... Approved.%n", amount, upiId);
        return true;
    }

    @Override
    public String getPaymentType() { return "UPI"; }

    @Override
    public String getMaskedIdentifier() { return upiId; }
}

// 3. Crypto Implementation
class CryptoPayment implements PaymentMethod {
    private String walletAddress;
    private String network;

    public CryptoPayment(String walletAddress, String network) {
        this.walletAddress = walletAddress;
        this.network = (network != null) ? network : "Ethereum";
    }

    @Override
    public boolean validateCredentials() {
        return walletAddress != null && walletAddress.startsWith("0x") && walletAddress.length() >= 10;
    }

    @Override
    public double calculateFee(double amount) {
        return 4.50; // Network gas fee
    }

    @Override
    public boolean processPayment(double amount) {
        if (!validateCredentials()) return false;
        System.out.printf("Broadcasting $%.2f transaction to %s blockchain... Confirmed.%n", amount, network);
        return true;
    }

    @Override
    public String getPaymentType() { return "CRYPTO_" + network.toUpperCase(); }

    @Override
    public String getMaskedIdentifier() {
        if (walletAddress.length() > 8) {
            return walletAddress.substring(0, 6) + "..." + walletAddress.substring(walletAddress.length() - 4);
        }
        return walletAddress;
    }
}

// 4. Decoupled Payment Gateway (Zero instanceof checks!)
class PaymentGateway {
    public boolean processOrder(String orderId, double amount, PaymentMethod method) {
        System.out.println("-------------------------------------------------------");
        System.out.printf("Processing Order %s | Amount: $%.2f%n", orderId, amount);

        if (method == null) {
            System.err.println("Transaction Failed: No payment method selected.");
            return false;
        }

        if (!method.validateCredentials()) {
            System.err.printf("Transaction Failed: Invalid credentials for %s.%n", method.getPaymentType());
            return false;
        }

        double fee = method.calculateFee(amount);
        double total = amount + fee;

        boolean success = method.processPayment(total);
        if (success) {
            printReceipt(orderId, method, amount, fee, total);
            return true;
        } else {
            System.err.println("Transaction Failed: Payment network rejected charge.");
            return false;
        }
    }

    private void printReceipt(String orderId, PaymentMethod method, double amt, double fee, double total) {
        System.out.println("=======================================================");
        System.out.println("                  PAYMENT RECEIPT                      ");
        System.out.println("=======================================================");
        System.out.printf("Order ID:         %s%n", orderId);
        System.out.printf("Payment Method:   %s%n", method.getPaymentType());
        System.out.printf("Account Ref:      %s%n", method.getMaskedIdentifier());
        System.out.printf("Subtotal:         $%.2f%n", amt);
        System.out.printf("Processing Fee:   $%.2f%n", fee);
        System.out.printf("Total Charged:    $%.2f%n", total);
        System.out.println("Status:           AUTHORIZED / PAID");
        System.out.println("=======================================================\n");
    }
}

